insert into change_headers (id, ts) values (74, '2026-11-15') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (74, 'ru', 'Профиль теперь можно перенести на другое устройство без файла: выберите «Передать…» в списке профилей (или кнопку с QR-кодом в «Управлении профилями…») и откройте ссылку на другом устройстве либо отсканируйте QR-код камерой телефона. Большой профиль показывается серией из нескольких кодов — отсканируйте их все, в любом порядке. Переносятся аккаунт, планеты, луны, ручные правки и настройки вселенной; ресурсы на планетах — нет. На сервер ничего не отправляется: профиль передаётся внутри самой ссылки.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'en', 'A profile can now be moved to another device without a file: choose "Transfer…" in the profile list (or the QR code button in "Manage profiles…"), then open the link on the other device or scan the QR code with your phone''s camera. A large profile is shown as a series of several codes: scan them all, in any order. The account, planets, moons, manual edits and universe settings are carried over; the resources on the planets are not. Nothing is sent to the server: the profile travels inside the link itself.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'pt', 'Um perfil pode agora ser passado para outro dispositivo sem ficheiro: escolha «Transferir…» na lista de perfis (ou o botão do código QR em «Gerir perfis…») e abra a ligação no outro dispositivo ou leia o código QR com a câmara do telemóvel. Um perfil grande é mostrado como uma série de vários códigos: leia-os todos, por qualquer ordem. São transferidos a conta, os planetas, as luas, as alterações manuais e as definições do universo; os recursos nos planetas não. Nada é enviado ao servidor: o perfil viaja dentro da própria ligação.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'de', 'Ein Profil lässt sich jetzt ohne Datei auf ein anderes Gerät übertragen: Wähle „Übertragen…“ in der Profilliste (oder die QR-Code-Schaltfläche unter „Profile verwalten…“) und öffne den Link auf dem anderen Gerät oder scanne den QR-Code mit der Handykamera. Ein großes Profil wird als Serie mehrerer Codes angezeigt: Scanne sie alle, in beliebiger Reihenfolge. Übertragen werden Account, Planeten, Monde, manuelle Änderungen und Universumseinstellungen, die Rohstoffe auf den Planeten nicht. An den Server wird nichts gesendet: Das Profil steckt im Link selbst.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'pl', 'Profil można teraz przenieść na inne urządzenie bez pliku: wybierz „Przenieś…” na liście profili (albo przycisk z kodem QR w „Zarządzaj profilami…”) i otwórz link na drugim urządzeniu lub zeskanuj kod QR aparatem telefonu. Duży profil jest wyświetlany jako seria kilku kodów: zeskanuj je wszystkie, w dowolnej kolejności. Przenoszone są konto, planety, księżyce, ręczne zmiany i ustawienia uniwersum; surowce na planetach nie. Nic nie jest wysyłane na serwer: profil jest zawarty w samym linku.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'es', 'Ahora un perfil se puede pasar a otro dispositivo sin archivo: elige «Transferir…» en la lista de perfiles (o el botón del código QR en «Gestionar perfiles…») y abre el enlace en el otro dispositivo o escanea el código QR con la cámara del móvil. Un perfil grande se muestra como una serie de varios códigos: escanéalos todos, en cualquier orden. Se transfieren la cuenta, los planetas, las lunas, los cambios manuales y los ajustes del universo; los recursos de los planetas, no. No se envía nada al servidor: el perfil viaja dentro del propio enlace.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'fr', 'Un profil peut désormais être transféré sur un autre appareil sans fichier : choisissez « Transférer… » dans la liste des profils (ou le bouton du code QR dans « Gérer les profils… »), puis ouvrez le lien sur l''autre appareil ou scannez le code QR avec l''appareil photo du téléphone. Un profil volumineux s''affiche en une série de plusieurs codes : scannez-les tous, dans n''importe quel ordre. Le compte, les planètes, les lunes, les modifications manuelles et les paramètres de l''univers sont transférés ; les ressources sur les planètes, non. Rien n''est envoyé au serveur : le profil voyage dans le lien lui-même.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'it', 'Ora un profilo si può trasferire su un altro dispositivo senza file: scegli «Trasferisci…» nell''elenco dei profili (o il pulsante del codice QR in «Gestisci profili…») e apri il link sull''altro dispositivo oppure inquadra il codice QR con la fotocamera del telefono. Un profilo grande viene mostrato come una serie di più codici: inquadrali tutti, in qualsiasi ordine. Vengono trasferiti account, pianeti, lune, modifiche manuali e impostazioni dell''universo; le risorse sui pianeti no. Al server non viene inviato nulla: il profilo viaggia dentro il link stesso.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'nl', 'Een profiel kan nu zonder bestand naar een ander apparaat worden overgezet: kies "Overzetten…" in de profiellijst (of de QR-codeknop bij "Profielen beheren…") en open de link op het andere apparaat of scan de QR-code met de camera van je telefoon. Een groot profiel wordt als een reeks van meerdere codes getoond: scan ze allemaal, in willekeurige volgorde. Account, planeten, manen, handmatige wijzigingen en universuminstellingen gaan mee; de grondstoffen op de planeten niet. Er gaat niets naar de server: het profiel zit in de link zelf.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'sk', 'Profil teraz môžete preniesť na iné zariadenie bez súboru: vyberte „Preniesť…“ v zozname profilov (alebo tlačidlo s QR kódom v „Spravovať profily…“) a otvorte odkaz na druhom zariadení alebo naskenujte QR kód fotoaparátom telefónu. Veľký profil sa zobrazí ako séria niekoľkých kódov: naskenujte ich všetky, v ľubovoľnom poradí. Prenášajú sa účet, planéty, mesiace, ručné úpravy a nastavenia vesmíru; suroviny na planétach nie. Na server sa nič neodosiela: profil je priamo v odkaze.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'tr', 'Bir profil artık dosya olmadan başka bir cihaza aktarılabilir: profil listesinde «Aktar…» seçeneğini (ya da «Profilleri yönet…» içindeki QR kod düğmesini) seçin ve bağlantıyı diğer cihazda açın veya QR kodu telefonun kamerasıyla okutun. Büyük bir profil birkaç koddan oluşan bir seri olarak gösterilir: hepsini herhangi bir sırayla okutun. Hesap, gezegenler, aylar, elle yapılan değişiklikler ve evren ayarları aktarılır; gezegenlerdeki kaynaklar aktarılmaz. Sunucuya hiçbir şey gönderilmez: profil bağlantının içinde taşınır.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'bs', 'Profil se sada može prenijeti na drugi uređaj bez datoteke: odaberite „Prenesi…“ na listi profila (ili dugme s QR kodom u „Upravljaj profilima…“) i otvorite link na drugom uređaju ili skenirajte QR kod kamerom telefona. Veliki profil prikazuje se kao serija od nekoliko kodova: skenirajte ih sve, bilo kojim redom. Prenose se nalog, planete, mjeseci, ručne izmjene i postavke univerzuma; resursi na planetama ne. Ništa se ne šalje na server: profil se prenosi unutar samog linka.') on duplicate key update description = values(description);
